package com.arqly.backend.repository;
import com.arqly.backend.entity.*;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface NotificationRepository extends JpaRepository<Notification,UUID>{ Optional<Notification> findByIdAndTenantIdAndRecipientUserId(UUID id,UUID tenantId,UUID userId); boolean existsByTenantIdAndRecipientUserIdAndDeduplicationKey(UUID tenantId,UUID userId,String key); long countByTenantIdAndRecipientUserIdAndStatus(UUID tenantId,UUID userId,NotificationStatus status); @Query("select n from Notification n where n.tenant.id=:tenant and n.recipientUser.id=:user and (:status is null or n.status=:status) and (:category is null or n.category=:category) and (:priority is null or n.priority=:priority) order by n.createdAt desc") Page<Notification> list(@Param("tenant") UUID tenant,@Param("user") UUID user,@Param("status") NotificationStatus status,@Param("category") NotificationCategory category,@Param("priority") NotificationPriority priority,Pageable pageable); }
